B.atL=new A.ci(1,"Ba\u015flang\u0131\xe7","\xd6\u011f\xfcn, uyku ve enerji g\xfcnl\xfc\u011f\xfc ba\u015flat.","Ba\u015flang\u0131\xe7 ad\u0131m\u0131n\u0131 kaydet.","Kamp neyi \xf6l\xe7er?","Bu kamp\u0131n ba\u015far\u0131 \xf6l\xe7\xfct\xfc tart\u0131 de\u011fil, g\xfcnl\xfck davran\u0131\u015f: g\xf6rev tamamlama, enerji, uyku ve tok hissetme.",u.L)
B.atH=new A.ci(2,"Su","Ki\u015fisel su hedefini tamamla.","+1.000 ad\u0131m.","Su hedefin nas\u0131l hesapland\u0131?","Hedefin kilonun her 30 kilogram\u0131 i\xe7in yakla\u015f\u0131k 1 litre \xfczerinden hesaplan\u0131r ve 1,5\u20133,5 litre aras\u0131nda tutulur. Hareket etti\u011fin g\xfcn biraz artar. Sa\u011fl\u0131k durumun gerektiriyorsa hedefi diyetisyenin belirler.",u.L)
B.au3=new A.ci(3,"\u0130lk \xf6\u011f\xfcn","\u0130lk \xf6\u011f\xfcne protein + lif ekle.","15 dk y\xfcr\xfcy\xfc\u015f.","Kahvalt\u0131 \u015fart m\u0131?","Kahvalt\u0131n\u0131n herkes i\xe7in \u015fart oldu\u011funu g\xf6steren g\xfc\xe7l\xfc bir kan\u0131t yok. \xd6nemli olan g\xfcn\xfcn ilk \xf6\u011f\xfcn\xfcn\xfcn dengeli olmas\u0131 ve sana iyi gelen bir d\xfczen.",u.L)
B.atG=new A.ci(4,"Tabak modeli","\u0130ki \xf6\u011f\xfcnde taba\u011f\u0131n yar\u0131s\u0131 sebze olsun.","15 dk y\xfcr\xfcy\xfc\u015f + esneme.","Sebzede renk \xe7e\u015fitlili\u011fi","Farkl\u0131 renkteki sebze ve meyveler farkl\u0131 vitamin, mineral ve bitki bile\u015fenleri ta\u015f\u0131r. Haftada m\xfcmk\xfcn oldu\u011funca \xe7ok renk hedefle.",u.L)
B.atJ=new A.ci(5,"Lif","G\xfcnde 1 kez baklagil ye.","10 dk g\xfc\xe7 hareketi.","Lif ve tokluk","Mercimek, nohut ve fasulye hem lif hem protein kayna\u011f\u0131d\u0131r; toklu\u011fu destekler ve ekonomiktir.",u.L)
B.au9=new A.ci(6,"\u015eekerli i\xe7ecek","\u015eekerli i\xe7ecek yerine maden suyu-limon ya da ayran se\xe7.","20 dk y\xfcr\xfcy\xfc\u015f.","Gizli \u015feker","Bir kutu (330 mL) kola yakla\u015f\u0131k 35 g, yani 7\u20138 k\xfcp \u015feker i\xe7erir. \u0130\xe7ecekten gelen \u015feker tokluk hissi vermeden enerji ekler.",u.L)
B.atU=new A.ci(7,"Hafta 1 geri bak\u0131\u015f",'En kolay al\u0131\u015fkanl\u0131\u011f\u0131n\u0131 se\xe7 ve "sabit" olarak i\u015faretle.',"Haftan\u0131n en uzun y\xfcr\xfcy\xfc\u015f\xfcn\xfc tekrarla.","Al\u0131\u015fkanl\u0131k d\xf6ng\xfcs\xfc","Al\u0131\u015fkanl\u0131k \xfc\xe7 par\xe7adan olu\u015fur: tetik, davran\u0131\u015f, \xf6d\xfcl. Ayn\u0131 tetikle ayn\u0131 davran\u0131\u015f\u0131 tekrarlamak onu zamanla otomatikle\u015ftirir.",u.L)
B.atK=new A.ci(8,"Uyku","Yat\u0131\u015f saatini sabitle, yatmadan 30 dk \xf6nce ekran\u0131 b\u0131rak.","20 dk y\xfcr\xfcy\xfc\u015f.","Uyku ve i\u015ftah","K\u0131sa uyku, i\u015ftah\u0131 d\xfczenleyen hormonlar\u0131 etkileyebilir ve ertesi g\xfcn y\xfcksek enerjili yiyecek iste\u011fini art\u0131rabilir.",u.U)
B.atE=new A.ci(9,"A\xe7l\u0131k \xf6l\xe7e\u011fi","Her \xf6\u011f\xfcn \xf6ncesi ve sonras\u0131 a\xe7l\u0131\u011f\u0131n\u0131 1\u201310 aras\u0131nda puanla.","10 dk g\xfc\xe7 + esneme.","Fiziksel ve duygusal a\xe7l\u0131k","Fiziksel a\xe7l\u0131k yava\u015f gelir ve herhangi bir yiyecekle ge\xe7er. Duygusal a\xe7l\u0131k ani gelir, belirli bir yiyecek ister ve doyduktan sonra da s\xfcrebilir.",u.U)
B.au6=new A.ci(10,"Tetikleyiciler","Plans\u0131z yedi\u011fin bir an\u0131 yaz: saat, yer, duygu.","20 dk y\xfcr\xfcy\xfc\u015f.","Duygusal yeme bir sinyaldir","Duygusal yeme su\xe7 de\u011fil; bir ihtiyac\u0131n sinyalidir. Tetikleyiciyi fark etmek, ona ba\u015fka bir yan\u0131t vermenin ilk ad\u0131m\u0131d\u0131r.","Plans\u0131z bir an ya\u015fad\u0131ysan, ba\u015far\u0131s\u0131zl\u0131k de\u011fil, veri toplad\u0131n.")
B.au5=new A.ci(11,"Stres","4-7-8 nefes egzersizini g\xfcnde 2 kez yap.","15 dk do\u011fada y\xfcr\xfcy\xfc\u015f.","Stres ve i\u015ftah","Stres baz\u0131 ki\u015filerde i\u015ftah\u0131 art\u0131r\u0131r, baz\u0131lar\u0131nda azalt\u0131r. K\u0131sa nefes egzersizleri ve y\xfcr\xfcy\xfc\u015f, stres an\u0131nda yeme\u011fe alternatif olabilir.",u.U)
B.au1=new A.ci(12,"Alternatif davran\u0131\u015f","Tetikleyici an i\xe7in 3 alternatif yaz (y\xfcr\xfcy\xfc\u015f, arama, du\u015f).","25 dk y\xfcr\xfcy\xfc\u015f.",'"E\u011fer-o zaman" plan\u0131','"E\u011fer ak\u015fam can\u0131m tatl\u0131 isterse, o zaman \xf6nce bir bardak su i\xe7ip 5 dakika y\xfcr\xfcyece\u011fim" gibi \xf6nceden yap\u0131lm\u0131\u015f planlar davran\u0131\u015f\u0131 de\u011fi\u015ftirmeyi kolayla\u015ft\u0131r\u0131r.',u.U)
B.atZ=new A.ci(13,"Yava\u015f yemek","2 \xf6\u011f\xfcn\xfc ekrans\u0131z ye.","10 dk g\xfc\xe7 hareketi.","Fark\u0131ndal\u0131kla yeme","Yeme\u011fin rengine, kokusuna ve tad\u0131na dikkat etmek hem keyfi art\u0131r\u0131r hem de toklu\u011fu fark etmeyi kolayla\u015ft\u0131r\u0131r.",u.U)
B.atC=new A.ci(14,"Hafta 2 geri bak\u0131\u015f","Uyku ve enerji puanlar\u0131n\u0131 Hafta 1 ile k\u0131yasla.","Sevdi\u011fin hareketi tekrarla.","Kendine \u015fefkat","Kendine \u015fefkatle yakla\u015fan ki\u015filerin kayma sonras\u0131 yeniden ba\u015flamas\u0131 daha kolayd\u0131r. M\xfckemmel de\u011fil, s\xfcrd\xfcr\xfclebilir.","Yar\u0131 yoldan fazlas\u0131n\u0131 ge\xe7tin. En zor k\u0131s\u0131m genelde tam buras\u0131d\u0131r ve sen buradas\u0131n.")
B.au_=new A.ci(15,"Men\xfc planlama","Haftal\u0131k men\xfc \u015fablonunu doldur.","25 dk y\xfcr\xfcy\xfc\u015f.","Plan \u015fablonu nas\u0131l kullan\u0131l\u0131r?","\xd6nce ana \xf6\u011f\xfcnlerin protein kayna\u011f\u0131n\u0131 se\xe7, sonra sebze ve tah\u0131l\u0131 ekle. Ayn\u0131 yeme\u011fi iki g\xfcn kullanmak plan\u0131 kolayla\u015ft\u0131r\u0131r.",u.N)
B.atF=new A.ci(16,"Al\u0131\u015fveri\u015f","Listeyle al\u0131\u015fveri\u015fe git, etiket oku.","15 dk g\xfc\xe7 hareketi.","Etiket okuma","100 g ba\u015f\u0131na \u015feker, tuz ve doymu\u015f ya\u011f de\u011ferlerini kar\u015f\u0131la\u015ft\u0131r. \u0130\xe7indekiler listesinin ilk \xfc\xe7 maddesi \xfcr\xfcn\xfcn \xe7o\u011funu olu\u015fturur.",u.N)
B.au0=new A.ci(17,"Haz\u0131rl\u0131k","30 dakikal\u0131k haftal\u0131k mutfak haz\u0131rl\u0131\u011f\u0131 yap.","25 dk y\xfcr\xfcy\xfc\u015f.","Toplu pi\u015firme ve saklama","Pi\u015fmi\u015f yeme\u011fi 2 saat i\xe7inde buzdolab\u0131na koy, 3\u20134 g\xfcn i\xe7inde t\xfcket ya da porsiyonlay\u0131p dondur.",u.N)
B.atV=new A.ci(18,"Sosyal sofra","Davette ya da d\u0131\u015far\u0131da yemekte tabak modelini uygula.","Dans, bisiklet ya da y\xfcr\xfcy\xfc\u015f, 30 dk.","Dengede kalmak",u.G,u.C)
B.au7=new A.ci(19,"Hareketi sabitlemek","Haftal\u0131k hareket takvimini yaz (haftada 150 dk hedefi).","15 dk g\xfc\xe7 + 15 dk y\xfcr\xfcy\xfc\u015f.","Ne kadar hareket?","D\xfcnya Sa\u011fl\u0131k \xd6rg\xfct\xfc yeti\u015fkinlere haftada en az 150\u2013300 dakika orta yo\u011funlukta hareket ve haftada 2 g\xfcn kas g\xfc\xe7lendirici egzersiz \xf6nerir.",u.N)
B.atN=new A.ci(20,"Zor g\xfcn plan\u0131",'Kendi "zor g\xfcn kiti"ni yaz: 3 kolay \xf6\u011f\xfcn, 1 hareket, 1 destek ki\u015fisi.',"30 dk y\xfcr\xfcy\xfc\u015f.","Kayma normaldir","Her rutin zaman zaman aksar. \xd6nemli olan geri d\xf6n\xfc\u015f plan\u0131n\u0131n haz\u0131r olmas\u0131.",u.N)
B.atX=new A.ci(21,"Devam plan\u0131","3 sabit al\u0131\u015fkanl\u0131k se\xe7 ve 2 hafta sonras\u0131 i\xe7in kontrol tarihi koy.","Kutlama y\xfcr\xfcy\xfc\u015f\xfc.","66 g\xfcn ger\xe7e\u011fi","21 g\xfcnde al\u0131\u015fkanl\u0131k tamamen oturmaz; ara\u015ft\u0131rmalarda ortalama 66 g\xfcn bulundu. Kamp temeli att\u0131, \u015fimdi s\xfcrd\xfcrme d\xf6nemi ba\u015fl\u0131yor.","Bu kamp bitti, senin rutinin bitmedi. Kendi plan\u0131n\u0131 yazd\u0131n; art\u0131k yol senin.")
