B.aue=new A.jC(21,"21 G\xfcnl\xfck Challenge","Kurallar de\u011fil, rutinler.","Daha \xf6nce diyet yap\u0131p b\u0131rakan, s\xfcrd\xfcr\xfclebilir bir d\xfczen isteyenler","Uyku, stres, duygusal yeme, haz\u0131rl\u0131k rutini ve kamp sonras\u0131 devam plan\u0131",B.aDF)
B.atI=new A.ci(1,"Ba\u015flang\u0131\xe7","3 \xf6\u011f\xfcn\xfc foto\u011frafla kaydet, sadece g\xf6zlemle.","Ba\u015flang\u0131\xe7 ad\u0131m say\u0131n\u0131 kaydet.","Dengeli sofra nedir?","T\xfcrkiye Beslenme Rehberi (T\xdcBER) dengeli tabakta sebze-meyve, tam tah\u0131l, protein kaynaklar\u0131 ve s\xfct grubunun bir arada olmas\u0131n\u0131 \xf6nerir. Bug\xfcn sadece sofrana bak.","On be\u015f g\xfcn boyunca kendi sofran\u0131n mimar\u0131s\u0131n.")
B.atT=new A.ci(2,"Protein","Her ana \xf6\u011f\xfcnde avu\xe7 i\xe7i kadar bir protein kayna\u011f\u0131 olsun.","20 dk y\xfcr\xfcy\xfc\u015f.","Neden \xf6nce protein?","Protein toklu\u011fu en uzun tutan besin \xf6gesidir ve kilo verirken kas kayb\u0131n\u0131 azaltmaya yard\u0131m eder. Bu kampta karbonhidrat saym\u0131yoruz; \xf6nce protein ve life bak\u0131yoruz.",u.x)
B.atQ=new A.ci(3,"Lif","G\xfcne en az 1 kez baklagil ya da tam tah\u0131l ekle.","20 dk y\xfcr\xfcy\xfc\u015f + 5 dk esneme.","Lif ve tokluk","Lif toklu\u011fu destekler ve ba\u011f\u0131rsak sa\u011fl\u0131\u011f\u0131 i\xe7in \xf6nemlidir. Yeti\u015fkinler i\xe7in g\xfcnl\xfck yakla\u015f\u0131k 25 g lif \xf6nerilir (EFSA); baklagil, sebze, meyve ve tam tah\u0131llar iyi kaynaklard\u0131r.",u.x)
B.aua=new A.ci(4,"Protein da\u011f\u0131l\u0131m\u0131","Proteini g\xfcne yay: kahvalt\u0131, \xf6\u011fle ve ak\u015famda ayr\u0131 kaynak se\xe7.","Evde 10 dk g\xfc\xe7 hareketi (duvara \u015f\u0131nav, sandalyeden kalk\u0131\u015f).","Proteini g\xfcne yaymak","Proteini tek \xf6\u011f\xfcnde toplamak yerine \xf6\u011f\xfcnlere yaymak toklu\u011fu ve kas sa\u011fl\u0131\u011f\u0131n\u0131 destekler. Yumurta, yo\u011furt, peynir, baklagil, bal\u0131k ve tavuk d\xf6n\xfc\u015f\xfcml\xfc kullan\u0131labilir.",u.x)
B.atW=new A.ci(5,"Sebze yar\u0131s\u0131","\u0130ki \xf6\u011f\xfcnde taba\u011f\u0131n yar\u0131s\u0131n\u0131 sebzeyle doldur.","25 dk y\xfcr\xfcy\xfc\u015f.","Hacim ve tokluk","Sebzeler az enerjiyle \xe7ok hacim ve lif sa\u011flar. Taba\u011f\u0131n yar\u0131s\u0131 sebze olunca ayn\u0131 toklu\u011fa daha dengeli bir tabakla ula\u015f\u0131rs\u0131n.",u.x)
B.atA=new A.ci(6,"Planlama","Yar\u0131nki 3 \xf6\u011f\xfcn\xfc bu ak\u015fam yaz.","20 dk y\xfcr\xfcy\xfc\u015f.","Plan neden i\u015fe yarar?","Ne yiyece\u011fini \xf6nceden bilmek g\xfcn i\xe7indeki karar y\xfck\xfcn\xfc azalt\u0131r. Plan bir kural de\u011fil, yar\u0131nki sana b\u0131rakt\u0131\u011f\u0131n bir nottur.",u.P)
B.au4=new A.ci(7,"Etiket okuma","Evdeki 3 paketli \xfcr\xfcn\xfcn etiketinde \u015feker, tuz ve lif miktar\u0131n\u0131 bul.","25 dk y\xfcr\xfcy\xfc\u015f.","Etiket nas\u0131l okunur?","\xdcr\xfcnleri kar\u015f\u0131la\u015ft\u0131r\u0131rken 100 g ba\u015f\u0131na de\u011ferlere bak: \u015feker, tuz, doymu\u015f ya\u011f ve lif. \u0130\xe7indekiler listesi en \xe7ok bulunandan en aza do\u011fru s\u0131ralan\u0131r.",u.P)
B.au2=new A.ci(8,"A\xe7l\u0131k-tokluk","Yeme\u011fe ba\u015flamadan ve bitirince a\xe7l\u0131\u011f\u0131n\u0131 1\u201310 aras\u0131nda puanla.","20 dk y\xfcr\xfcy\xfc\u015f + esneme.","A\xe7l\u0131k \xf6l\xe7e\u011fi","Fiziksel a\xe7l\u0131k yava\u015f gelir ve herhangi bir yiyecekle ge\xe7er; duygusal a\xe7l\u0131k ani gelir ve belirli bir yiyecek ister. Puanlamak fark\u0131 g\xf6rmeni kolayla\u015ft\u0131r\u0131r.","V\xfccudunu dinlemek bir beceri; her g\xfcn biraz daha iyi duyacaks\u0131n.")
B.atx=new A.ci(9,"Ak\u015fam rutini",'Ak\u015fam yeme\u011finden sonra mutfa\u011f\u0131 "kapat": di\u015f f\u0131r\xe7ala, bitki \xe7ay\u0131 haz\u0131rla.',"10 dk ak\u015fam y\xfcr\xfcy\xfc\u015f\xfc.","Gece at\u0131\u015ft\u0131rmas\u0131 nereden gelir?","Gece at\u0131\u015ft\u0131rmas\u0131n\u0131n s\u0131k nedenlerinden biri g\xfcn i\xe7inde yetersiz yemektir. Ak\u015fam\u0131n huzurlu ge\xe7mesi g\xfcnd\xfcz d\xfczenli ve proteinli beslenmekle ba\u015flar.","Ak\u015fam\u0131n huzurlu ge\xe7mesi, g\xfcnd\xfcz iyi beslenmekle ba\u015flar.")
B.atO=new A.ci(10,"Haz\u0131rl\u0131k","Hafta haz\u0131rl\u0131\u011f\u0131: 1 baklagil ha\u015fla, 1 sebze do\u011fra, 1 sos haz\u0131rla.","Evde 15 dk g\xfc\xe7 + esneme.","Haz\u0131rl\u0131k yapan mutfak","\xd6nceden haz\u0131rlanm\u0131\u015f birka\xe7 temel malzeme, yorgun bir ak\u015famda haz\u0131r g\u0131daya uzanma ihtiyac\u0131n\u0131 azalt\u0131r.","Bug\xfcnk\xfc 30 dakika, haftan\u0131n 3 saatini kurtar\u0131r.")
B.atY=new A.ci(11,"Y\xf6resel sofran","Kendi y\xf6re mutfa\u011f\u0131ndan bir yeme\u011fi tabak modeline uydur.","25 dk y\xfcr\xfcy\xfc\u015f ya da halay, horon, zeybek: sevdi\u011fin bir dans.","Yasak yemek yok","Hamsi, karalahana, zeytinya\u011fl\u0131 otlar, bulgur, mercimek, tarhana... Her y\xf6renin mutfa\u011f\u0131nda protein ve lif zengini yemekler var. Ki\u015fisel plan\u0131n senin sofrana g\xf6re haz\u0131rlan\u0131r.",u.H)
B.aty=new A.ci(12,"D\u0131\u015far\u0131da yemek","D\u0131\u015far\u0131da ya da paket servis yerken \xf6nce proteini ve sebzeyi se\xe7.","25 dk y\xfcr\xfcy\xfc\u015f ya da dans.","Men\xfcden se\xe7im","Izgara, ha\u015flama ve f\u0131r\u0131n y\xf6ntemlerini se\xe7; yan\u0131na salata ya da sebze ekle. Sosu ayr\u0131 istemek k\xfc\xe7\xfck ama etkili bir ad\u0131m.",u.H)
B.atR=new A.ci(13,"Sosyal sofra","Davette ya da misafirlikte taba\u011f\u0131n\u0131 sebzeyle ba\u015flat, yava\u015f ye.","20 dk y\xfcr\xfcy\xfc\u015f + 10 dk g\xfc\xe7.","Dengede kalmak",u.G,u.C)
B.atz=new A.ci(14,"Zor g\xfcn kiti",'Kendi "zor g\xfcn kiti"ni yaz: 3 kolay proteinli \xf6\u011f\xfcn, 1 hareket, 1 destek ki\u015fisi.',"30 dk y\xfcr\xfcy\xfc\u015f.","Kayma normaldir","Her rutin zaman zaman aksar. \xd6nemli olan geri d\xf6n\xfc\u015f plan\u0131n\u0131n haz\u0131r olmas\u0131. Bir kayma, kamp\u0131n bitti\u011fi anlam\u0131na gelmez.",u.H)
B.atP=new A.ci(15,"Kendi men\xfcn","Gelecek haftan\u0131n men\xfcs\xfcn\xfc protein + lif \u015fablonuyla planla.","15 g\xfcn\xfcn en sevdi\u011fin hareketini tekrarla.","Kamp sonras\u0131","S\xfcrd\xfcr\xfclebilir olan, m\xfckemmel olandan iyidir. Bu on be\u015f g\xfcnde en kolay s\xfcrd\xfcrd\xfc\u011f\xfcn \xfc\xe7 al\u0131\u015fkanl\u0131\u011f\u0131 se\xe7 ve \xf6n\xfcm\xfczdeki haftaya ta\u015f\u0131.","On be\u015f g\xfcn\xfc tamamlad\u0131n. Sofran art\u0131k seni tan\u0131yor.")
