B.r7=s(["\u0e21\u0e01\u0e23\u0e32\u0e04\u0e21","\u0e01\u0e38\u0e21\u0e20\u0e32\u0e1e\u0e31\u0e19\u0e18\u0e4c","\u0e21\u0e35\u0e19\u0e32\u0e04\u0e21","\u0e40\u0e21\u0e29\u0e32\u0e22\u0e19","\u0e1e\u0e24\u0e29\u0e20\u0e32\u0e04\u0e21","\u0e21\u0e34\u0e16\u0e38\u0e19\u0e32\u0e22\u0e19","\u0e01\u0e23\u0e01\u0e0e\u0e32\u0e04\u0e21","\u0e2a\u0e34\u0e07\u0e2b\u0e32\u0e04\u0e21","\u0e01\u0e31\u0e19\u0e22\u0e32\u0e22\u0e19","\u0e15\u0e38\u0e25\u0e32\u0e04\u0e21","\u0e1e\u0e24\u0e28\u0e08\u0e34\u0e01\u0e32\u0e22\u0e19","\u0e18\u0e31\u0e19\u0e27\u0e32\u0e04\u0e21"],t.s)
B.aPU=new A.yg("Al\u0131\u015fkanl\u0131k olu\u015fmas\u0131 ne kadar s\xfcrer?","Lally P, van Jaarsveld CHM, Potts HWW, Wardle J","European Journal of Social Psychology",2010,"10.1002/ejsp.674","Yeni bir sa\u011fl\u0131k davran\u0131\u015f\u0131 (\xf6r. \xf6\u011fle yeme\u011finde meyve yemek) ne kadar s\xfcrede otomatikle\u015fir?","Kat\u0131l\u0131mc\u0131lar se\xe7tikleri davran\u0131\u015f\u0131 12 hafta boyunca her g\xfcn ayn\u0131 ba\u011flamda tekrarlad\u0131. Davran\u0131\u015f\u0131n otomatikle\u015fmesi ortalama 66 g\xfcn s\xfcrd\xfc; ki\u015fiden ki\u015fiye 18 ile 254 g\xfcn aras\u0131nda de\u011fi\u015fti. Bir g\xfcn\xfc ka\xe7\u0131rmak s\xfcreci belirgin \u015fekilde bozmad\u0131.","\xc7al\u0131\u015fmay\u0131 tamamlayan kat\u0131l\u0131mc\u0131 say\u0131s\u0131 azd\u0131 (yakla\u015f\u0131k 80 ki\u015fi) ve otomatiklik ki\u015filerin kendi beyan\u0131na dayan\u0131yordu.","Al\u0131\u015fkanl\u0131k 21 g\xfcnde tamamlanmaz; kamp temeli atar. Bir g\xfcn\xfc ka\xe7\u0131rmak her \u015feyi bozmaz, kald\u0131\u011f\u0131n yerden devam et.")
B.aPV=new A.yg("Ultra i\u015flenmi\u015f g\u0131dalar ne kadar yememize yol a\xe7\u0131yor?","Hall KD ve ark.","Cell Metabolism",2019,"10.1016/j.cmet.2019.05.008","Ultra i\u015flenmi\u015f g\u0131dalardan olu\u015fan bir beslenme, i\u015flenmemi\u015f g\u0131dalara g\xf6re enerji al\u0131m\u0131n\u0131 de\u011fi\u015ftirir mi?","20 yeti\u015fkin, kontroll\xfc bir ortamda iki\u015fer hafta boyunca ya ultra i\u015flenmi\u015f ya da i\u015flenmemi\u015f g\u0131dalarla beslendi; istedikleri kadar yiyebildiler. Ultra i\u015flenmi\u015f d\xf6nemde g\xfcnde ortalama yakla\u015f\u0131k 500 kcal daha fazla yediler ve kilo ald\u0131lar; i\u015flenmemi\u015f d\xf6nemde kilo verdiler.","Kat\u0131l\u0131mc\u0131 say\u0131s\u0131 k\xfc\xe7\xfckt\xfc, s\xfcre k\u0131sayd\u0131 ve ortam g\xfcnl\xfck hayattan farkl\u0131yd\u0131.","Her \u015feyi yasaklamak gerekmez; taba\u011f\u0131nda i\u015flenmemi\u015f ya da az i\u015flenmi\u015f besinlerin pay\u0131n\u0131 art\u0131rmak toklu\u011fu kolayla\u015ft\u0131rabilir.")
B.aPT=new A.yg("G\xfcnl\xfck ad\u0131m say\u0131s\u0131 ve sa\u011fl\u0131k","Paluch AE ve ark.","The Lancet Public Health",2022,"10.1016/S2468-2667(21)00302-9","G\xfcnl\xfck ad\u0131m say\u0131s\u0131 ile \xf6l\xfcm riski aras\u0131nda nas\u0131l bir ili\u015fki var?","15 kohortun birle\u015fik analizinde daha fazla ad\u0131m atanlarda \xf6l\xfcm riski daha d\xfc\u015f\xfckt\xfc. Fayda 60 ya\u015f ve \xfczerinde g\xfcnde yakla\u015f\u0131k 6.000\u20138.000, 60 ya\u015f alt\u0131nda yakla\u015f\u0131k 8.000\u201310.000 ad\u0131mda d\xfczle\u015fiyordu.","G\xf6zlemsel bir \xe7al\u0131\u015fmad\u0131r; neden-sonu\xe7 ili\u015fkisi kan\u0131tlamaz. Kat\u0131l\u0131mc\u0131lar\u0131n \xe7o\u011fu y\xfcksek gelirli \xfclkelerdendi.","10.000 ad\u0131m sihirli bir say\u0131 de\u011fil. Bug\xfcnk\xfc ad\u0131m\u0131na 1.000 eklemek ger\xe7ek\xe7i bir ba\u015flang\u0131\xe7.")
B.aPS=new A.yg("Karbonhidrat kalitesi ve lif","Reynolds A, Mann J, Cummings J, Winter N, Mete E, Te Morenga L","The Lancet",2019,"10.1016/S0140-6736(18)31809-9","Lif ve tam tah\u0131l t\xfcketimi kronik hastal\u0131k riskleriyle nas\u0131l ili\u015fkili?","Yakla\u015f\u0131k 185 g\xf6zlemsel \xe7al\u0131\u015fma ve 58 klinik \xe7al\u0131\u015fman\u0131n analizinde, g\xfcnde 25\u201329 g lif alanlarda en az lif alanlara g\xf6re t\xfcm nedenlere ba\u011fl\u0131 \xf6l\xfcm, kalp hastal\u0131\u011f\u0131, tip 2 diyabet ve kolorektal kanser riski y\xfczde 15\u201330 daha d\xfc\u015f\xfckt\xfc.","Sonu\xe7lar\u0131n \xe7o\u011fu g\xf6zlemsel \xe7al\u0131\u015fmalardan gelir; lif t\xfcketenlerin di\u011fer ya\u015fam al\u0131\u015fkanl\u0131klar\u0131 da farkl\u0131 olabilir.","G\xfcne bir kez baklagil, \xf6\u011f\xfcnlere sebze ve beyaz ekmek yerine tam tah\u0131ll\u0131 ekmek eklemek lif hedefine yakla\u015ft\u0131r\u0131r.")
